// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }
    function testFuzz_property(uint256 seed) public {
        vm.assume(seed < type(uint256).max);
        // the caller of airDrop must be a contract answering supportsToken like Bank
        AirdropCaller caller = new AirdropCaller(c);
        vm.assume(c.tokenBalance(address(caller)) == 0);
        caller.go();
        assertEq(c.tokenBalance(address(caller)), 20);
    }
}

contract AirdropCaller {
    ModifierEntrancy c;
    constructor(ModifierEntrancy _c) { c = _c; }
    function go() external { c.airDrop(); }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
